/**
 * Pattern knob labels / effects for the Director timeline.
 * Data from patterns-catalog.js (generated by toolchain/make_absolute_ready.py).
 */
import catalog from "./patterns-catalog.js";

export const DEFAULT_PARAM_LABELS = ["Param 1", "Param 2", "Param 3", "Param 4"];

function normKey(name) {
  return String(name || "")
    .trim()
    .toLowerCase()
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ");
}

const BY_KEY = Object.create(null);
for (const p of catalog.patterns || []) {
  const labels = (p.knobs || []).slice(0, 4);
  while (labels.length < 4) labels.push("Param " + (labels.length + 1));
  const entry = {
    name: p.name,
    labels,
    params: p.params || [],
    absoluteReady: !!p.absoluteReady,
    slug: p.slug || ""
  };
  const k = normKey(p.name);
  BY_KEY[k] = entry;
  BY_KEY[k.replace(/\s+/g, "")] = entry;
  if (p.slug) {
    BY_KEY[normKey(p.slug)] = entry;
    BY_KEY[String(p.slug).toLowerCase()] = entry;
  }
}

export function patternMetaFor(patternName) {
  const key = normKey(patternName);
  if (!key) return null;
  return BY_KEY[key] || BY_KEY[key.replace(/\s+/g, "")] || null;
}

export function paramLabelsFor(patternName) {
  const meta = patternMetaFor(patternName);
  if (meta && meta.labels) return meta.labels.slice();
  return DEFAULT_PARAM_LABELS.slice();
}

export function paramEffectsFor(patternName) {
  const meta = patternMetaFor(patternName);
  if (!meta || !meta.params) {
    return DEFAULT_PARAM_LABELS.map((label, i) => ({
      channel: i + 1,
      label,
      effect: "Parameter " + (i + 1),
      wire: "0..1000"
    }));
  }
  return meta.params.slice();
}

export function listPatterns() {
  return (catalog.patterns || [])
    .slice()
    .sort((a, b) => String(a.name).localeCompare(String(b.name), undefined, { sensitivity: "base" }));
}

/** Catalog display name for MQTT (`Origin`, `Cell Wave`), or trimmed input if unknown. */
export function canonicalPatternName(raw) {
  const trimmed = String(raw || "").trim();
  if (!trimmed) return "";
  const meta = patternMetaFor(trimmed);
  if (meta && meta.name) return meta.name;
  return trimmed;
}

/** Catalog slug if known (`cell_wave`), else empty. */
export function patternSlugFor(patternName) {
  const meta = patternMetaFor(patternName);
  return meta && meta.slug ? String(meta.slug) : "";
}

export function searchPatterns(query, limit) {
  const all = listPatterns();
  const q = String(query || "")
    .trim()
    .toLowerCase()
    .replace(/[_-]+/g, " ");
  const hits = q
    ? all.filter((p) => {
        const name = String(p.name || "").toLowerCase();
        const slug = String(p.slug || "").toLowerCase().replace(/_/g, " ");
        return name.includes(q) || slug.includes(q);
      })
    : all;
  if (limit == null || limit <= 0) return hits;
  return hits.slice(0, limit);
}
